def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items):return '<ul>'+''.join(f'<li>{i}</li>' for i in items)+'</ul>'
def OL(items):return '<ol>'+''.join(f'<li>{i}</li>' for i in items)+'</ol>'
def LN(d,c='ln'):return f'<path d="{d}" class="{c}"/>'
def kz(x,n=1):return f'{x:.{n}f}'.replace('.',',')

# ---------- numbers (recomputed) ----------
def lin(v,vmin,vmax,xmin,xmax):return xmin+(v-vmin)/(vmax-vmin)*(xmax-xmin)
assert lin(12,4,20,0,16)==8 and lin(4,4,20,0,16)==0 and lin(20,4,20,0,16)==16 and lin(8,4,20,0,16)==4
assert lin(12,4,20,0,10)==5 and lin(12,4,20,0,12)==6                 # lesson 2 numbers
assert lin(5,0,10,-20,80)==30 and lin(2.5,0,10,-20,80)==5 and 300/30==10 and 80-(-20)==100
assert abs(lin(7,4,20,0,5)-0.9375)<1e-9 and lin(12,4,20,0,5)==2.5 and abs(lin(12,4,20,0,4.6)-2.3)<1e-9
assert round((8.0+8.4+7.8+8.2)/4,1)==8.1
w=[8,8,8,8];avg=[]
for x in (10,10,10,10):w=w[1:]+[x];avg.append(sum(w)/4)
assert avg==[8.5,9.0,9.5,10.0]

