f_sensor=F(fig_sensor(),'Датчиктің кірісі — физикалық шама, шығысы — электрлік сигнал (4 түрдің бірі)')

def fig_scale():
    o=TL(10,24,'Қысым, бар','t-s mu')+TL(10,166,'Ток, мА','t-s mu')+LN('M40 70 L300 70')+LN('M40 130 L300 130')
    for k,v in enumerate((0,4,8,12,16)):
        x=40+65*k;mid=(k==2)
        o+=LN(f'M{x} 66 L{x} 74')+LN(f'M{x} 126 L{x} 134')+T(x,58,str(v),'t-s'+(' ac t-b' if mid else ''))+T(x,152,str(4+4*k),'t-s'+(' ac t-b' if mid else ''))
        o+=LN(f'M{x} 74 L{x} 126','lna' if mid else 'ln dash')
    return S(340,176,o,'Сызықтық масштабтау: 4–20 мА тоғы 0–16 бар қысымына сәйкес келеді')
f_scale=F(fig_scale(),'Сызықтық сәйкестік: 4 мА — 0 бар, 20 мА — 16 бар; 12 мА диапазонның ортасында, яғни 8 бар')

